<template><el-card><h1>单词检索</h1><el-input v-model="query" placeholder="beautiful"><template #append><el-button @click="search">搜索</el-button></template></el-input><el-empty v-if="!results.length"/><el-card v-for="r in results" :key="r.word" shadow="never"><h2>{{r.word}}</h2><p>来源：{{r.source}}</p></el-card></el-card></template><script setup>import{ref}from'vue';import{searchWord}from'@/api/client';const query=ref('beautiful');const results=ref([]);async function search(){const{data}=await searchWord(query.value);results.value=data.data.items}</script>
